"""Generate exact reference cursor and cell expectations for horizontal edits."""
import argparse
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
source = json.loads((root/'research/horizontal-xterm.json').read_text(encoding='utf-8'))


def literal(text):
    return '"'+''.join('\\%03o'%b if b < 32 or b >= 127 else
        '\\'+chr(b) if chr(b) in '\\"' else chr(b) for b in text.encode())+'"'


cases = list(source['cases'].items())
cells = [(c['row'], c['column']) for c in cases[0][1]['cells']]
outputs = {
    'horizontal_oracle_cases.h': '/* Generated by tests/generate_horizontal_oracle.py. */\n'+
        'static const unsigned horizontal_cells[][2] = {'+','.join('{%d,%d}'%c for c in cells)+'};\n'+
        'static const struct { const char *name, *sequence, *reply; unsigned cells[%d]; } horizontal_oracle[] = {\n'%len(cells)+
        ''.join('    {'+', '.join(map(literal, [n, c['input'], c['cursor_reply']]))+', {'+
                ','.join(str(v['checksum']) for v in c['cells'])+'}},\n' for n,c in cases)+'};\n',
    'horizontal_oracle_cases.py': '# Generated by tests/generate_horizontal_oracle.py.\nCASES = [\n'+
        ''.join('    '+repr((n,c['sequence'],c['reply']))+',\n' for n,c in cases)+']\n',
}
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
for name, content in outputs.items():
    path = root/'tests'/name
    if args.check: assert path.read_text(encoding='utf-8') == content, 'Regenerate '+name
    else: path.write_text(content, encoding='utf-8')
